///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Modify
 * @description Modify 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Modify = async function () {
    const sbmOptions = {
        id: "tx_fn_Modify",
        method: "post",
        action: "/account/corpDiscls.do",
        ref: "dma_ModifyReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_Delete
 * @description Delete 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Delete = async function () {
    const sbmOptions = {
        id: "tx_fn_Delete",
        method: "post",
        action: "/account/corpDiscls.do",
        ref: "dma_DeleteReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name popZipCode
 * @description pop Zip Code 처리
 * @param {String} _tpCd _tpCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.popZipCode = async function (_tpCd) {
    scwin.selFrm = $c.util.getComponent('elwLiquidDisclsChrgForm' + _tpCd);
    const zipSearchURL = '/ui/jsp/JLDINF90009.xml';
    scwin.setZipCode_recv(await $c.win.openPopup(zipSearchURL, { id: "zipWin", scrollbars: false, resizable: false, width: "445", height: "600", type: "pageFramePopup" }, Object.assign({ method: "loadInitPage" }, { selFrm: (typeof scwin.selFrm !== 'undefined' ? scwin.selFrm : undefined) })));
};

/**
 * @method
 * @name setZipCode
 * @description set Zip Code 처리
 * @param {*} _zipCode _zipCode
 * @param {*} _address _address
 * @returns {void}
 * @hidden N
 */
scwin.setZipCode = function (_zipCode, _address) {
    $c.util.getComponent("ipt_locZipcd").setValue(_zipCode);
    $c.util.getComponent("ipt_locAddr").setValue(_address);
    $c.util.getComponent('dma_ModifyReq').set('applYn', "Y");
};

/**
 * @method
 * @name modify
 * @description modify 처리
 * @param {String} _doFlag _doFlag
 * @param {String} _tpCd _tpCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.modify = async function (_doFlag, _tpCd) {
    const frm = $c.util.getComponent('elwLiquidDisclsChrgForm' + _tpCd);
    if (_doFlag === 'insert') {
        if (await $c.fil.checkRequired($c.util.getComponent('ipt_chrgNm'))) {
            return;
        }
        if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = ""; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent('ipt_chrgNm'))) {
            return;
        }
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_jobtitlNm'))) {
        return;
    }
    if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = ""; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent('ipt_jobtitlNm'))) {
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_depNm'))) {
        return;
    }
    if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = ""; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent('ipt_depNm'))) {
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_telNo1')) || await $c.fil.checkRequired($c.util.getComponent('ipt_telNo2')) || await $c.fil.checkRequired($c.util.getComponent('ipt_telNo3'))) {
        return;
    }
    if (!($c.fil.isNumberInput($c.util.getComponent('ipt_telNo1')) && $c.fil.isNumberInput($c.util.getComponent('ipt_telNo2')) && $c.fil.isNumberInput($c.util.getComponent('ipt_telNo3')))) {
        await $c.win.alert('유선전화번호는 숫자만 입력하세요');
        return;
    }
    if (!($c.fil.isNumberInput($c.util.getComponent('ipt_chrgInnrNo')))) {
        await $c.win.alert('내선은 숫자만 입력하세요');
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('slc_cellphoneNo1')) || await $c.fil.checkRequired($c.util.getComponent('ipt_cellphoneNo2')) || await $c.fil.checkRequired($c.util.getComponent('ipt_cellphoneNo3'))) {
        return;
    }
    if (!($c.fil.isNumberInput($c.util.getComponent('slc_cellphoneNo1')) && $c.fil.isNumberInput($c.util.getComponent('ipt_cellphoneNo2')) && $c.fil.isNumberInput($c.util.getComponent('ipt_cellphoneNo3')))) {
        await $c.win.alert('휴대전화번호는 숫자만 입력하세요');
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_faxNo1')) || await $c.fil.checkRequired($c.util.getComponent('ipt_faxNo2')) || await $c.fil.checkRequired($c.util.getComponent('ipt_faxNo3'))) {
        return;
    }
    if (!($c.fil.isNumberInput($c.util.getComponent('ipt_faxNo1')) && $c.fil.isNumberInput($c.util.getComponent('ipt_faxNo2')) && $c.fil.isNumberInput($c.util.getComponent('ipt_faxNo3')))) {
        await $c.win.alert('FAX는 숫자만 입력하세요');
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_email1')) || await $c.fil.checkRequired($c.util.getComponent('ipt_email2'))) {
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_birthYear')) || await $c.fil.checkRequired($c.util.getComponent('ipt_birthMonth')) || await $c.fil.checkRequired($c.util.getComponent('ipt_birthDay'))) {
        return;
    }
    if (!await $c.fil.checkDateParts($c.util.getComponent('ipt_birthYear'), $c.util.getComponent('ipt_birthMonth'), $c.util.getComponent('ipt_birthDay'), false)) {
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('slc_eduCompltYn'))) {
        return;
    }
    const eduCompltYn = $c.util.getComponent('slc_eduCompltYn').getValue();
    if (eduCompltYn === 'Y') {
        if (await $c.fil.checkRequired($c.util.getComponent('ipt_eduCompltYear')) || await $c.fil.checkRequired($c.util.getComponent('ipt_eduCompltMonth')) || await $c.fil.checkRequired($c.util.getComponent('ipt_eduCompltDay'))) {
            return;
        }
        if (!await $c.fil.checkDateParts($c.util.getComponent('ipt_eduCompltYear'), $c.util.getComponent('ipt_eduCompltMonth'), $c.util.getComponent('ipt_eduCompltDay'), false)) {
            return;
        }
        if (await $c.fil.checkRequired($c.util.getComponent('ipt_eduCrsNm'))) {
            return;
        }
        if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = ""; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent('ipt_eduCrsNm'))) {
            return;
        }
    } else {
        if (!$c.util.isEmpty(($c.util.getComponent('ipt_eduCompltYear')).getValue()) || !$c.util.isEmpty(($c.util.getComponent('ipt_eduCompltMonth')).getValue()) || !$c.util.isEmpty(($c.util.getComponent('ipt_eduCompltDay')).getValue())) {
            await $c.win.alert("'" + $c.util.getComponent('slc_eduCompltYn').title + "' 항목이  'N' 으로 되어있습니다.\n'" + ((__a) => ((__a && __a.getAttribute) ? ((__a.getAttribute("alt") || __a.getAttribute("toolTip") || (__a.getTitle ? (__a.getTitle() ?? "") : "")) || "") : (__a ? (__a.alt ?? "") : "")))($c.util.getComponent('ipt_eduCompltYear')) + "' 항목이 불필요합니다");
            $c.util.getComponent("ipt_eduCompltYear").focus();
            return;
        }
        if (!$c.util.isEmpty(($c.util.getComponent('ipt_eduCrsNm')).getValue())) {
            await $c.win.alert("'" + $c.util.getComponent('slc_eduCompltYn').title + "' 항목이  'N' 으로 되어있습니다.\n'" + ((__a) => ((__a && __a.getAttribute) ? ((__a.getAttribute("alt") || __a.getAttribute("toolTip") || (__a.getTitle ? (__a.getTitle() ?? "") : "")) || "") : (__a ? (__a.alt ?? "") : "")))($c.util.getComponent('ipt_eduCrsNm')) + "' 항목이 불필요합니다");
            $c.util.getComponent("ipt_eduCrsNm").focus();
            return;
        }
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_chrgDesignYear')) || await $c.fil.checkRequired($c.util.getComponent('ipt_chrgDesignMonth')) || await $c.fil.checkRequired($c.util.getComponent('ipt_chrgDesignDay'))) {
        return;
    }
    if (!await $c.fil.checkDateParts($c.util.getComponent('ipt_chrgDesignYear'), $c.util.getComponent('ipt_chrgDesignMonth'), $c.util.getComponent('ipt_chrgDesignDay'), false)) {
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('slc_disclsProfsYn'))) {
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_locZipcd'))) {
        return;
    }
    if (!($c.fil.isZipCodeInput($c.util.getComponent('ipt_locZipcd')))) {
        await $c.win.alert('우편번호는 숫자만 입력하세요');
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_locAddr'))) {
        return;
    }
    if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = ""; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent('ipt_locAddr'))) {
