    $c.util.getComponent('dma_ModifyReq').set('eduCompltDd', $c.util.getComponent('ipt_eduCompltYear').getValue()+ $c.util.getComponent('ipt_eduCompltMonth').getValue()+ $c.util.getComponent('ipt_eduCompltDay').getValue());
