/**
 * @method
 * @name initValue
 * @description init Value 처리
 * @returns {void}
 * @hidden N
 */
scwin.initValue = function () {
    for (let i = 1; i <= 3; i++) {
        const frm = $c.util.getComponent('elwLiquidDisclsChrgForm' + i);
        ((v) => { let cur = String(v ?? ""); for (let i = 3; i >= 1; i--) { const idx = cur.lastIndexOf("-"); const part = cur.substring(idx + 1); const c = $c.util.getComponent("telNo" + i); if (c && c.setValue) { c.setValue(part); } cur = cur.substring(0, idx); } })($c.util.getComponent('dma_ModifyReq').get('telNo'));
        ((v) => { let cur = String(v ?? ""); for (let i = 3; i >= 1; i--) { const idx = cur.lastIndexOf("-"); const part = cur.substring(idx + 1); const c = $c.util.getComponent("cellphoneNo" + i); if (c && c.setValue) { c.setValue(part); } cur = cur.substring(0, idx); } })($c.util.getComponent('dma_ModifyReq').get('cellphoneNo'));
        ((v) => { let cur = String(v ?? ""); for (let i = 3; i >= 1; i--) { const idx = cur.lastIndexOf("-"); const part = cur.substring(idx + 1); const c = $c.util.getComponent("faxNo" + i); if (c && c.setValue) { c.setValue(part); } cur = cur.substring(0, idx); } })($c.util.getComponent('dma_ModifyReq').get('faxNo'));
        ((v) => { let cur = String(v ?? ""); for (let i = 2; i >= 1; i--) { const idx = cur.lastIndexOf("@"); const part = cur.substring(idx + 1); const c = $c.util.getComponent("email" + i); if (c && c.setValue) { c.setValue(part); } cur = cur.substring(0, idx); } })($c.util.getComponent('dma_ModifyReq').get('email'));
        const birthddVal = $c.util.getComponent('dma_ModifyReq').get('birthdd');
        $c.util.getComponent("ipt_birthYear").setValue(birthddVal.substring(0, 4));
        $c.util.getComponent("ipt_birthMonth").setValue(birthddVal.substring(4, 6));
        $c.util.getComponent("ipt_birthDay").setValue(birthddVal.substring(6));
        const eduCompltDdVal = $c.util.getComponent('dma_ModifyReq').get('eduCompltDd');
        $c.util.getComponent("ipt_eduCompltYear").setValue(eduCompltDdVal.substring(0, 4));
        $c.util.getComponent("ipt_eduCompltMonth").setValue(eduCompltDdVal.substring(4, 6));
        $c.util.getComponent("ipt_eduCompltDay").setValue(eduCompltDdVal.substring(6));
        const chrgDesignDdVal = $c.util.getComponent('dma_ModifyReq').get('chrgDesignDd');
        $c.util.getComponent("ipt_chrgDesignYear").setValue(chrgDesignDdVal.substring(0, 4));
        $c.util.getComponent("ipt_chrgDesignMonth").setValue(chrgDesignDdVal.substring(4, 6));
        $c.util.getComponent("ipt_chrgDesignDay").setValue(chrgDesignDdVal.substring(6));
    }
};

/**
 * @method
 * @name setZipCode_recv
 * @description 팝업 회신 수신 — 팝업이 남긴 인자를 as-is 함수 인자 순서로 펼쳐 넘긴다.
